{"content": """"Panel: species distribution across ecosystem."""
from _panels_data import _walk, _rel, _img_b64, BG, FG, ACC, DIM
from collections import Counter
import matplotlib.pyplot as plt
import numpy as np


def build():
    files = _walk()
    counter = Counter()
    for p in files:
        for tag in _classify(p):
            counter[tag] += 1
    items = counter.most_common()
    labels = [k for k, _ in items]
    vals = [v for _, v in items]
    cols = plt.cm.plasma(np.linspace(0.15, 0.85, max(1, len(labels))))
    fig, ax = plt.subplots(figsize=(10, 5.5), facecolor=BG)
    bars = ax.barh(labels[::-1], vals[::-1], color=cols[::-1])
    ax.set_facecolor(BG)
    for s in ax.spines.values():
        s.set_color(DIM)
    ax.tick_params(colors=FG)
    ax.set_title("Species Distribution", color=ACC, fontsize=13,
                  fontweight="bold", loc="left")
    ax.grid(color=DIM, alpha=0.25)
    for b, v in zip(bars, vals[::-1]):
        ax.text(v + 0.5, b.get_y() + b.get_height() / 2, str(v),
                color=FG, va="center", fontsize=9)
    img = _img_b64(fig)
    return {"chart": "species", "labels": labels, "vals": vals, "img": img}


def _classify(p):
    n = p.name.lower()
    tags = []
